
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_op_xalpha_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_op_xalpha", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.223804808808741e-02, -5.216695590975447e-02, -5.206257512858214e-02, -5.190796872464081e-02, -5.167611312935815e-02, -5.132230981442119e-02, -5.076924124891956e-02, -4.987601916570988e-02, -4.837237449911810e-02, -4.572423241377717e-02, -4.079462032543787e-02, -3.319845906449748e-02, -3.094606303271446e-02, -2.862093342838950e-02, -2.317483594045617e-02, -1.505854700478726e-02, -6.762119953093237e-03, -1.750893980251364e-03, -2.241367637109960e-04, -1.263376362363720e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


